import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Link } from 'react-router-dom';
import { OrganizationChart } from './OrganizationChart';
import { prepareEmployeePhoto } from './photo';
import { SelectField } from './SelectField';
import { FinalPaySettlementPanel } from './FinalPaySettlementPanel';

type Company = { id: string; companyCode: string; legalName: string; countryCode: string; timezone: string; tradeName: string | null; entityType: string | null; registrationNumber: string | null; ownerName: string | null; ownerEmail: string | null; ownerPhone: string | null; addressLine1: string | null; addressLine2: string | null; city: string | null; region: string | null; postalCode: string | null; industry: string | null };
type CompanyDraft = { companyCode: string; legalName: string; tradeName: string; entityType: string; registrationNumber: string; ownerName: string; ownerEmail: string; ownerPhone: string; addressLine1: string; addressLine2: string; city: string; region: string; postalCode: string; countryCode: string; timezone: string; industry: string };
const emptyCompanyDraft: CompanyDraft = { companyCode: '', legalName: '', tradeName: '', entityType: '', registrationNumber: '', ownerName: '', ownerEmail: '', ownerPhone: '', addressLine1: '', addressLine2: '', city: '', region: '', postalCode: '', countryCode: 'PH', timezone: 'Asia/Manila', industry: '' };
function companyDraftFrom(company: Company): CompanyDraft { return { companyCode: company.companyCode, legalName: company.legalName, tradeName: company.tradeName || '', entityType: company.entityType || '', registrationNumber: company.registrationNumber || '', ownerName: company.ownerName || '', ownerEmail: company.ownerEmail || '', ownerPhone: company.ownerPhone || '', addressLine1: company.addressLine1 || '', addressLine2: company.addressLine2 || '', city: company.city || '', region: company.region || '', postalCode: company.postalCode || '', countryCode: company.countryCode || 'PH', timezone: company.timezone || 'Asia/Manila', industry: company.industry || '' }; }
type Branch = { id: string; branchCode: string; branchName: string; regionCode: string };
type Department = { id: string; code: string; name: string; parentId: string | null; active: boolean };
type Position = { id: string; code: string; name: string; active: boolean };
type Employee = { id: string; companyId: string; employeeNumber: string; firstName: string; lastName: string; hireDate: string; employmentStatus: string; photoDataUrl: string | null; departmentId: string | null; departmentName: string | null; positionId: string | null; positionName: string | null };
type DirectoryFilters = { status: string[]; departmentId: string[]; positionId: string[]; hireWindow: string[]; photo: string[] };
type DirectoryView = { id: string; name: string; filters: DirectoryFilters; columns: string[] };
const directoryColumns = [
  { id: 'employee', label: 'Employee' }, { id: 'number', label: 'Employee no.' },
  { id: 'department', label: 'Department' }, { id: 'position', label: 'Position' },
  { id: 'status', label: 'Employment' }, { id: 'hireDate', label: 'Hire date' },
  { id: 'actions', label: 'Actions' },
];
const defaultDirectoryFilters: DirectoryFilters = { status: [], departmentId: [], positionId: [], hireWindow: [], photo: [] };
const defaultDirectoryColumns = directoryColumns.map(column => column.id);
function readDirectoryViews(companyId: string): DirectoryView[] {
  try {
    const parsed = JSON.parse(localStorage.getItem(`apexHrm.peopleViews.${companyId}`) || '[]') as Partial<DirectoryView>[];
    const asArray = (value: unknown) => Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : typeof value === 'string' && value !== 'ALL' ? [value] : [];
    return parsed.filter(item => item && typeof item.name === 'string').map((item, index) => {
      const filters = (item.filters || {}) as unknown as Record<string, unknown>;
      return { id: item.id || `saved-${index}`, name: item.name!, columns: Array.isArray(item.columns) ? item.columns : defaultDirectoryColumns, filters: { status: asArray(filters.status), departmentId: asArray(filters.departmentId), positionId: asArray(filters.positionId), hireWindow: asArray(filters.hireWindow), photo: asArray(filters.photo) } };
    });
  }
  catch { return []; }
}
function DirectoryColumnFilter({ label, value, options, onChange }: { label: string; value: string[]; options: { value: string; label: string }[]; onChange: (values: string[]) => void }) {
  const [open, setOpen] = useState(false); const [search, setSearch] = useState(''); const [draft, setDraft] = useState(value);
  const filtered = options.filter(option => option.label.toLowerCase().includes(search.toLowerCase()));
  return <span className="directory-column-filter"><button type="button" className={`directory-filter-trigger${value.length ? ' has-filter' : ''}`} aria-label={`Filter ${label}`} aria-expanded={open} title={`Filter ${label}`} onClick={() => { setDraft(value); setSearch(''); setOpen(current => !current); }}><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 4h14l-5.5 6.3v5.2l-3 1.5v-6.7L3 4Z" /></svg></button>{open && <span className="directory-filter-popover"><input type="search" value={search} onChange={event => setSearch(event.target.value)} placeholder={`Filter ${label.toLowerCase()}…`} aria-label={`Search ${label} values`} /><button type="button" className="directory-filter-option directory-filter-all" onClick={() => setDraft(draft.length === options.length ? [] : options.map(option => option.value))}><span className={`directory-filter-checkbox${draft.length === options.length && options.length ? ' checked' : ''}`}>{draft.length === options.length && options.length ? '✓' : ''}</span>Select all</button><span className="directory-filter-options">{filtered.map(option => <button type="button" className="directory-filter-option" key={option.value} aria-pressed={draft.includes(option.value)} onClick={() => setDraft(current => current.includes(option.value) ? current.filter(item => item !== option.value) : [...current, option.value])}><span className={`directory-filter-checkbox${draft.includes(option.value) ? ' checked' : ''}`}>{draft.includes(option.value) ? '✓' : ''}</span>{option.label}</button>)}</span><span className="directory-filter-actions"><button type="button" onClick={() => setDraft([])}>Clear</button><button type="button" className="apply" onClick={() => { onChange(draft); setOpen(false); }}>Apply</button></span></span>}</span>;
}
type Profile = { id: string; companyId: string; branchId: string | null; departmentId: string | null; employeeNumber: string; firstName: string; middleName: string | null; lastName: string; preferredName: string | null; suffix: string | null; hireDate: string; employmentStatus: string; employmentType: string; photoDataUrl: string | null };
type Assignment = { id: string; companyId: string; branchId: string | null; departmentId: string | null; positionId: string | null; effectiveDate: string; reason: string };
type EmploymentEvent = { id: string; effectiveDate: string; employmentType: string; employmentStatus: string; jobTitle: string | null; reason: string };
type Compensation = { id: string; effectiveDate: string; amount: number; currencyCode: string; payBasis: string; reason: string };
type PrivateData = { governmentId: string | null; contactEmail: string | null; mobile: string | null; bankAccount: string | null };
type Document = { id: string; category: string; filename: string; sha256: string; sizeBytes: number; expiresOn: string | null; version: number };
type HrCase = { id: string; type: string; status: string; effectiveDate: string; requestedBy: string; decidedBy: string | null };
type Requirement = { id: string; code: string; label: string; mandatory: boolean; status: string; evidenceDocumentId: string | null };
type Clearance = { id: string; code: string; label: string; required: boolean; status: string };
type Asset = { id: string; assetTag: string; description: string; status: string };
type Rehire = { id: string; effectiveDate: string; employmentType: string; status: string; requestedBy: string; approvedBy: string | null };

const employmentTypes = ['REGULAR', 'PROBATIONARY', 'CONTRACTUAL', 'PROJECT', 'SEASONAL', 'CASUAL', 'PART_TIME'];
const employmentStatuses = ['ACTIVE', 'ON_LEAVE', 'SUSPENDED', 'TERMINATED', 'RETIRED'];
const documentCategories = ['CONTRACT', 'IDENTITY', 'CERTIFICATION', 'ONBOARDING', 'SEPARATION', 'OTHER'];

function apiError(response: Response, body: string) {
  try { const parsed = JSON.parse(body) as { detail?: string; message?: string; error?: string }; return parsed.detail || parsed.message || parsed.error || `Request failed (HTTP ${response.status}).`; }
  catch { return body || `Request failed (HTTP ${response.status}).`; }
}

function dateToday() { return new Date().toISOString().slice(0, 10); }

export function PersonnelWorkspace({ token, roles, currentUserId, workspaceName, initialPage = 'people', onOpenNavigation }: { token: string; roles: string[]; currentUserId: string; workspaceName?: string | null; initialPage?: 'people' | 'organization' | 'policy' | 'onboarding' | 'documents'; onOpenNavigation?: () => void }) {
  const page = initialPage;
  const [companies, setCompanies] = useState<Company[]>([]);
  const [companyId, setCompanyId] = useState('');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [positions, setPositions] = useState<Position[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [employeeQuery, setEmployeeQuery] = useState('');
  const [showEmployeeForm, setShowEmployeeForm] = useState(false);
  const [mobileActionsOpen, setMobileActionsOpen] = useState(false);
  const [selected, setSelected] = useState<Employee | null>(null);
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const isOwner = roles.includes('ROLE_TENANT_ADMIN');
  const canHr = isOwner || roles.includes('ROLE_HR_ADMIN');
  const canPayroll = isOwner || roles.includes('ROLE_PAYROLL_OFFICER');
  const currentCompany = companies.find(company => company.id === companyId);
  const filteredEmployees = useMemo(() => employees.filter(employee => `${employee.employeeNumber} ${employee.firstName} ${employee.lastName} ${employee.employmentStatus}`.toLowerCase().includes(employeeQuery.toLowerCase())), [employees, employeeQuery]);

  async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
    const response = await fetch(path, { ...init, headers: { Authorization: `Bearer ${token}`, ...(init.body && !(init.body instanceof FormData) ? { 'Content-Type': 'application/json' } : {}), ...init.headers } });
    if (!response.ok) throw new Error(apiError(response, await response.text()));
    if (response.status === 204) return undefined as T;
    return response.json() as Promise<T>;
  }
  async function loadCompanies() {
    setLoading(true); setError('');
    try {
      const result = await request<Company[]>('/api/v1/companies'); setCompanies(result);
      if (result.length && !result.some(company => company.id === companyId)) setCompanyId(result[0].id);
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not load companies.'); }
    finally { setLoading(false); }
  }
  async function loadCompanyData(id = companyId) {
    if (!id) { setEmployees([]); setDepartments([]); setPositions([]); setBranches([]); return; }
    setLoading(true); setError('');
    try {
      const [people, teams, jobs, locations] = await Promise.all([
        request<Employee[]>(`/api/v1/personnel/employees?companyId=${encodeURIComponent(id)}`),
        request<Department[]>(`/api/v1/personnel/departments?companyId=${encodeURIComponent(id)}`),
        request<Position[]>(`/api/v1/personnel/positions?companyId=${encodeURIComponent(id)}`),
        request<Branch[]>(`/api/v1/companies/${id}/branches`),
      ]);
      setEmployees(people); setDepartments(teams); setPositions(jobs); setBranches(locations);
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not load workspace personnel.'); }
    finally { setLoading(false); }
  }
  useEffect(() => { void loadCompanies(); }, [token]);
  useEffect(() => { if (companyId) void loadCompanyData(companyId); }, [companyId, refreshKey]);
  function refresh() { setRefreshKey(value => value + 1); }
  async function submit(event: FormEvent, action: () => Promise<unknown>, message: string) {
    event.preventDefault(); setBusy(true); setError(''); setNotice('');
    try { await action(); setNotice(message); refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'The change could not be saved.'); }
    finally { setBusy(false); }
  }

  return <div className="people-workspace">
    {!selected && <header className="people-heading"><div className="people-heading-title">{page === 'people' && <>{onOpenNavigation && <button type="button" className="people-navigation-trigger" aria-label="Open navigation" onClick={onOpenNavigation}><span /><span /><span /></button>}<span className="people-page-icon" aria-hidden="true">♙</span></>}<div><p className="eyebrow">{page === 'people' || page === 'onboarding' || page === 'documents' ? 'PEOPLE OPERATIONS' : page === 'organization' ? 'ORGANIZATION MANAGEMENT' : 'WORKSPACE POLICIES'}</p><h1>{page === 'people' ? 'People' : page === 'organization' ? 'Organization' : page === 'policy' ? 'HR policies' : page === 'onboarding' ? 'Onboarding' : 'Documents'}</h1><p>{page === 'people' ? 'Employee records and effective dated people operations.' : page === 'organization' ? 'Build your organization from legal entities down to departments and sections.' : page === 'policy' ? 'Configure workspace rehire eligibility.' : page === 'onboarding' ? 'Manage employee onboarding checklists, evidence, and approvals.' : 'Upload, review, retain, and retrieve employee documents.'}</p></div></div><div className="people-heading-actions">{mobileActionsOpen && <button type="button" className="people-actions-dismiss" aria-label="Close page actions" onClick={() => setMobileActionsOpen(false)} />}<button type="button" className="people-actions-more" aria-label="Page actions" aria-haspopup="true" aria-expanded={mobileActionsOpen} onClick={() => setMobileActionsOpen(open => !open)}>···</button><div className={`people-heading-action-items${mobileActionsOpen ? ' is-open' : ''}`}>{page === 'people' && <Link className="people-back-dashboard" to="/dashboard/overview" onClick={() => setMobileActionsOpen(false)}>← Dashboard</Link>}{page !== 'organization' && companies.length > 0 && <label className="people-company-select"><span>Company</span><SelectField label="Select company" value={companyId} onChange={value => { setCompanyId(value); setMobileActionsOpen(false); }} options={companies.map(company => ({ value: company.id, label: `${company.companyCode} · ${company.legalName}` }))} /></label>}<button type="button" className="session-revoke" onClick={() => { refresh(); setMobileActionsOpen(false); }} disabled={loading}>↻ Refresh</button>{page === 'people' && currentCompany && !selected && canHr && <button type="button" className="security-submit people-add-button" onClick={() => { setShowEmployeeForm(value => !value); setMobileActionsOpen(false); }}>＋ Add employee</button>}</div></div></header>}
    {error && <div className="platform-alert" role="alert">{error}</div>}{notice && <p className="platform-notice" role="status">{notice}</p>}
    {loading && !companies.length ? <div className="people-card people-empty">Loading your organization…</div> : !companies.length && ['people', 'onboarding', 'documents'].includes(page) ? <CompanySetup request={request} onCreated={company => { setCompanies([company]); setCompanyId(company.id); setNotice('Company created. Add a branch, department, and positions in Organization.'); }} /> : page === 'organization' ? <OrganizationPage organizationName={workspaceName || 'Your organization'} companies={companies} company={currentCompany || null} onSelectCompany={setCompanyId} onCompanySaved={company => { setCompanies(current => current.some(item => item.id === company.id) ? current.map(item => item.id === company.id ? company : item) : [...current, company]); setCompanyId(company.id); }} branches={branches} positions={positions} request={request} submit={submit} busy={busy} onRefresh={refresh} /> : page === 'policy' ? <RehirePolicyPage request={request} submit={submit} busy={busy} /> : selected ? <EmployeeWorkspace employee={selected} company={currentCompany!} employees={employees} departments={departments} positions={positions} branches={branches} canHr={canHr} canPayroll={canPayroll} currentUserId={currentUserId} request={request} onBack={() => { setSelected(null); refresh(); }} initialTab={page === 'onboarding' ? 'HR lifecycle' : page === 'documents' ? 'Documents' : 'Profile'} /> : currentCompany ? <PeopleDirectory key={currentCompany.id} company={currentCompany} employees={filteredEmployees} departments={departments} positions={positions} query={employeeQuery} onQuery={value => { setEmployeeQuery(value); setShowEmployeeForm(false); }} canHr={canHr} request={request} submit={submit} busy={busy} onOpen={setSelected} onRefresh={refresh} showNew={showEmployeeForm} setShowNew={setShowEmployeeForm} /> : null}
  </div>;
}

function CompanySetup({ request, onCreated }: { request: <T>(path: string, init?: RequestInit) => Promise<T>; onCreated: (company: Company) => void }) {
  const [code, setCode] = useState(''); const [name, setName] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function create(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { onCreated(await request<Company>('/api/v1/companies', { method: 'POST', body: JSON.stringify({ companyCode: code, legalName: name }) })); } catch (e) { setError(e instanceof Error ? e.message : 'Could not create company.'); } finally { setBusy(false); } }
  return <section className="people-card people-company-empty"><span className="people-card-icon">⌂</span><p className="eyebrow">GET STARTED</p><h2>Create your company profile</h2><p>Your workspace is ready. Set up the legal entity before adding branches and staff.</p>{error && <div className="platform-alert" role="alert">{error}</div>}<form className="people-form people-company-form" onSubmit={event => void create(event)}><Field label="Company code"><input value={code} onChange={event => setCode(event.target.value)} required maxLength={40} pattern="[A-Za-z0-9_-]+" placeholder="MAIN" /></Field><Field label="Legal name"><input value={name} onChange={event => setName(event.target.value)} required maxLength={200} placeholder="Apex People Inc." /></Field><button type="submit" className="security-submit" disabled={busy}>{busy ? 'Creating…' : 'Create company'}</button></form></section>;
}

function PeopleDirectory({ company, employees, departments, positions, query, onQuery, canHr, request, submit, busy, onOpen, onRefresh, showNew, setShowNew }: { company: Company; employees: Employee[]; departments: Department[]; positions: Position[]; query: string; onQuery: (value: string) => void; canHr: boolean; request: <T>(path: string, init?: RequestInit) => Promise<T>; submit: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean; onOpen: (employee: Employee) => void; onRefresh: () => void; showNew: boolean; setShowNew: (show: boolean | ((value: boolean) => boolean)) => void }) {
  const [number, setNumber] = useState(''); const [first, setFirst] = useState(''); const [last, setLast] = useState(''); const [hireDate, setHireDate] = useState(dateToday());
  const [view, setView] = useState<'cards' | 'list'>('list'); const [currentPage, setCurrentPage] = useState(1); const [pageSize, setPageSize] = useState(10);
  const [filters, setFilters] = useState<DirectoryFilters>(defaultDirectoryFilters);
  const [columns, setColumns] = useState<string[]>(defaultDirectoryColumns);
  const [savedViews, setSavedViews] = useState<DirectoryView[]>(() => readDirectoryViews(company.id));
  const [activeViewId, setActiveViewId] = useState('all'); const [showColumnMenu, setShowColumnMenu] = useState(false);
  const [showDirectoryMore, setShowDirectoryMore] = useState(false);
  const [showSaveView, setShowSaveView] = useState(false); const [newViewName, setNewViewName] = useState('');
  useEffect(() => { localStorage.setItem(`apexHrm.peopleViews.${company.id}`, JSON.stringify(savedViews)); }, [company.id, savedViews]);
  const changeFilter = (key: keyof DirectoryFilters, value: string[]) => { setFilters(current => ({ ...current, [key]: value })); setActiveViewId('custom'); setCurrentPage(1); };
  const hasActiveFilters = Boolean(query.trim()) || Object.values(filters).some(values => values.length > 0);
  function clearFilters() {
    setFilters(defaultDirectoryFilters);
    onQuery('');
    setActiveViewId(columns.join('|') === defaultDirectoryColumns.join('|') ? 'all' : 'custom');
    setCurrentPage(1);
  }
  const filteredEmployees = useMemo(() => {
    const now = new Date();
    return employees.filter(employee => {
      if (filters.status.length && !filters.status.includes(employee.employmentStatus)) return false;
      if (filters.departmentId.length && (!employee.departmentId || !filters.departmentId.includes(employee.departmentId))) return false;
      if (filters.positionId.length && (!employee.positionId || !filters.positionId.includes(employee.positionId))) return false;
      const hired = new Date(`${employee.hireDate}T12:00:00`);
      if (filters.hireWindow.length && !filters.hireWindow.some(window => window === '90_DAYS' ? hired >= new Date(now.getFullYear(), now.getMonth(), now.getDate() - 90) : window === 'THIS_YEAR' && hired >= new Date(now.getFullYear(), 0, 1))) return false;
      if (filters.photo.length && !filters.photo.includes(employee.photoDataUrl ? 'HAS_PHOTO' : 'NO_PHOTO')) return false;
      return true;
    });
  }, [employees, filters]);
  const pageCount = Math.max(1, Math.ceil(filteredEmployees.length / pageSize));
  const pageEmployees = filteredEmployees.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  useEffect(() => { setCurrentPage(page => Math.min(page, pageCount)); }, [pageCount]);
  function applySavedView(saved: DirectoryView) { setFilters(saved.filters); setColumns(saved.columns); setActiveViewId(saved.id); setCurrentPage(1); }
  function saveCurrentView(event: FormEvent) {
    event.preventDefault(); const name = newViewName.trim(); if (!name) return;
    const saved: DirectoryView = { id: `view-${Date.now()}`, name, filters: { ...filters }, columns: [...columns] };
    setSavedViews(current => [...current, saved]); setActiveViewId(saved.id); setNewViewName(''); setShowSaveView(false);
  }
  function deleteSavedView(id: string) { setSavedViews(current => current.filter(saved => saved.id !== id)); if (activeViewId === id) setActiveViewId('all'); }
  async function create(event: FormEvent) { await submit(event, async () => { await request('/api/v1/personnel/employees', { method: 'POST', body: JSON.stringify({ companyId: company.id, employeeNumber: number, firstName: first, lastName: last, hireDate }) }); setShowNew(false); setNumber(''); setFirst(''); setLast(''); onRefresh(); }, 'Employee record created.'); }
  const visible = (id: string) => columns.includes(id);
  const statusFilter = <DirectoryColumnFilter label="employment status" value={filters.status} onChange={value => changeFilter('status', value)} options={employmentStatuses.map(status => ({ value: status, label: status.replaceAll('_', ' ') }))} />;
  const departmentFilter = <DirectoryColumnFilter label="department" value={filters.departmentId} onChange={value => changeFilter('departmentId', value)} options={departments.filter(item => item.active).map(item => ({ value: item.id, label: item.name }))} />;
  const positionFilter = <DirectoryColumnFilter label="position" value={filters.positionId} onChange={value => changeFilter('positionId', value)} options={positions.filter(item => item.active).map(item => ({ value: item.id, label: item.name }))} />;
  const hireDateFilter = <DirectoryColumnFilter label="hire date" value={filters.hireWindow} onChange={value => changeFilter('hireWindow', value)} options={[{ value: '90_DAYS', label: 'Hired in last 90 days' }, { value: 'THIS_YEAR', label: 'Hired this year' }]} />;
  const photoFilter = <DirectoryColumnFilter label="employee photo" value={filters.photo} onChange={value => changeFilter('photo', value)} options={[{ value: 'HAS_PHOTO', label: 'Has a photo' }, { value: 'NO_PHOTO', label: 'Missing a photo' }]} />;
  const columnChoices = <div className="people-columns-menu" role="group" aria-label="Choose visible columns">{directoryColumns.map(column => <label key={column.id}><input type="checkbox" checked={visible(column.id)} onChange={event => { setColumns(current => event.target.checked ? [...current, column.id] : current.filter(id => id !== column.id)); setActiveViewId('custom'); }} />{column.label}</label>)}</div>;
  const columnButton = <div className="people-columns-control"><button type="button" className="session-revoke" aria-expanded={showColumnMenu} onClick={() => setShowColumnMenu(open => !open)}>Columns ▾</button>{showColumnMenu && columnChoices}</div>;
  return <div className="people-card people-directory-card">
    <div className="people-directory-toolbar"><label className="platform-search people-search"><span aria-hidden="true">⌕</span><input value={query} onChange={event => { setCurrentPage(1); onQuery(event.target.value); }} placeholder="Search name, employee number, or status" /></label><div className="people-saved-views" role="tablist" aria-label="Saved employee views"><button type="button" role="tab" aria-selected={activeViewId === 'all'} className={activeViewId === 'all' ? 'active' : ''} onClick={() => { setFilters(defaultDirectoryFilters); setColumns(defaultDirectoryColumns); setActiveViewId('all'); setCurrentPage(1); }}>All employees</button>{savedViews.map(saved => <span className="people-saved-view" key={saved.id}><button type="button" role="tab" aria-selected={activeViewId === saved.id} className={activeViewId === saved.id ? 'active' : ''} onClick={() => applySavedView(saved)}>{saved.name}</button><button type="button" aria-label={`Delete saved view ${saved.name}`} title="Delete saved view" onClick={() => deleteSavedView(saved.id)}>×</button></span>)}{activeViewId === 'custom' && <span className="people-custom-view-label">Custom filters</span>}</div><div className="people-directory-actions"><div className="people-directory-standard-actions">{view === 'list' && columnButton}{hasActiveFilters && <button type="button" className="people-save-view-button people-clear-filters" onClick={clearFilters}>Clear filters</button>}<button type="button" className="people-save-view-button" onClick={() => setShowSaveView(open => !open)}>＋ Save view</button></div><button type="button" className="people-directory-more" aria-label="More directory options" aria-expanded={showDirectoryMore} onClick={() => setShowDirectoryMore(open => !open)}>•••</button>{showDirectoryMore && <><button type="button" className="people-directory-more-dismiss" aria-label="Close directory options" onClick={() => setShowDirectoryMore(false)} /><div className="people-directory-more-menu">{view === 'list' && columnButton}{hasActiveFilters && <button type="button" className="people-save-view-button people-clear-filters" onClick={() => { clearFilters(); setShowDirectoryMore(false); }}>Clear filters</button>}<button type="button" className="people-save-view-button" onClick={() => { setShowSaveView(true); setShowDirectoryMore(false); }}>＋ Save view</button></div></>}<div className="people-view-toggle" role="group" aria-label="Employee display mode"><button type="button" className={view === 'cards' ? 'active' : ''} aria-pressed={view === 'cards'} onClick={() => setView('cards')}><span aria-hidden="true">▦</span> Cards</button><button type="button" className={view === 'list' ? 'active' : ''} aria-pressed={view === 'list'} onClick={() => setView('list')}><span aria-hidden="true">☷</span> List</button></div></div></div>
    {view === 'cards' && <div className="people-directory-tools"><div className="people-directory-filters"><span className="people-filter-caption">Quick filters</span>{statusFilter}{departmentFilter}{positionFilter}{hireDateFilter}{photoFilter}</div></div>}
    {showSaveView && <form className="people-save-view-form" onSubmit={saveCurrentView}><label>View name<input value={newViewName} onChange={event => setNewViewName(event.target.value)} placeholder="e.g. Active team" maxLength={60} autoFocus required /></label><button type="submit" className="checklist-action">Save current view</button><button type="button" className="session-revoke" onClick={() => { setShowSaveView(false); setNewViewName(''); }}>Cancel</button></form>}
    {showNew && <form className="people-form people-create-form" onSubmit={event => void create(event)}><Field label="Employee number"><input value={number} onChange={event => setNumber(event.target.value)} required maxLength={50} pattern="[A-Za-z0-9_-]+" /></Field><Field label="First name"><input value={first} onChange={event => setFirst(event.target.value)} required maxLength={120} /></Field><Field label="Last name"><input value={last} onChange={event => setLast(event.target.value)} required maxLength={120} /></Field><Field label="Hire date"><input type="date" value={hireDate} max={dateToday()} onChange={event => setHireDate(event.target.value)} required /></Field><div className="people-form-actions"><button className="session-revoke" type="button" onClick={() => setShowNew(false)}>Cancel</button><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Create employee'}</button></div></form>}
    <div className="people-results-summary">{filteredEmployees.length} of {employees.length} employee{employees.length === 1 ? '' : 's'}{query ? ' found' : ''} · page {currentPage} of {pageCount}</div>
    {pageEmployees.length ? view === 'list' ? <div className="platform-table-wrap"><table className="platform-table people-table"><thead><tr>{visible('employee') && <th><span className="people-table-heading">EMPLOYEE{photoFilter}</span></th>}{visible('number') && <th>EMPLOYEE NO.</th>}{visible('department') && <th><span className="people-table-heading">DEPARTMENT{departmentFilter}</span></th>}{visible('position') && <th><span className="people-table-heading">POSITION{positionFilter}</span></th>}{visible('status') && <th><span className="people-table-heading">EMPLOYMENT{statusFilter}</span></th>}{visible('hireDate') && <th><span className="people-table-heading">HIRE DATE{hireDateFilter}</span></th>}{visible('actions') && <th></th>}</tr></thead><tbody>{pageEmployees.map(employee => <tr key={employee.id}>{visible('employee') && <td><span className="people-directory-identity">{employee.photoDataUrl ? <img src={employee.photoDataUrl} alt="" /> : <span>{employee.firstName.slice(0, 1)}{employee.lastName.slice(0, 1)}</span>}<strong>{employee.firstName} {employee.lastName}</strong></span></td>}{visible('number') && <td>{employee.employeeNumber}</td>}{visible('department') && <td>{employee.departmentName || '—'}</td>}{visible('position') && <td>{employee.positionName || '—'}</td>}{visible('status') && <td><span className={`platform-status-tag ${employee.employmentStatus === 'ACTIVE' ? 'active' : 'suspended'}`}>{employee.employmentStatus.replaceAll('_', ' ')}</span></td>}{visible('hireDate') && <td>{new Date(`${employee.hireDate}T12:00:00`).toLocaleDateString()}</td>}{visible('actions') && <td><button type="button" className="platform-text-action" onClick={() => onOpen(employee)}>Open profile →</button></td>}</tr>)}</tbody></table></div> : <div className="people-employee-grid">{pageEmployees.map(employee => <article className="people-employee-card" key={employee.id}><button type="button" className="people-employee-card-main" onClick={() => onOpen(employee)}>{employee.photoDataUrl ? <img src={employee.photoDataUrl} alt="" /> : <span className="people-employee-avatar">{employee.firstName.slice(0, 1)}{employee.lastName.slice(0, 1)}</span>}<span><strong>{employee.firstName} {employee.lastName}</strong><small>{employee.employeeNumber}</small></span></button><div className="people-employee-card-meta"><span className={`platform-status-tag ${employee.employmentStatus === 'ACTIVE' ? 'active' : 'suspended'}`}>{employee.employmentStatus.replaceAll('_', ' ')}</span><span>Hired {new Date(`${employee.hireDate}T12:00:00`).toLocaleDateString()}</span></div><button type="button" className="platform-text-action" onClick={() => onOpen(employee)}>Open profile →</button></article>)}</div> : <div className="people-empty">{view === 'list' && <div className="people-empty-filters"><label>Employee photo{photoFilter}</label><label>Department{departmentFilter}</label><label>Position{positionFilter}</label><label>Employment{statusFilter}</label><label>Hire date{hireDateFilter}</label></div>}<span>♙</span><strong>{query || filters.status.length || filters.departmentId.length || filters.positionId.length || filters.hireWindow.length || filters.photo.length ? 'No employees match these filters.' : 'No employees yet'}</strong><p>{canHr ? 'Add your first employee to start building the people directory.' : 'Your company employee directory is empty.'}</p>{canHr && !showNew && <button type="button" className="checklist-action" onClick={() => setShowNew(true)}>Add employee</button>}</div>}
    <footer className="people-pagination"><span>Showing {filteredEmployees.length ? (currentPage - 1) * pageSize + 1 : 0}–{Math.min(currentPage * pageSize, filteredEmployees.length)} of {filteredEmployees.length}</span><div><label>Rows <select value={pageSize} onChange={event => { setPageSize(Number(event.target.value)); setCurrentPage(1); }}><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option></select></label><button type="button" className="session-revoke" disabled={currentPage <= 1} onClick={() => setCurrentPage(page => Math.max(1, page - 1))}>Previous</button><span>Page {currentPage} of {pageCount}</span><button type="button" className="session-revoke" disabled={currentPage >= pageCount} onClick={() => setCurrentPage(page => Math.min(pageCount, page + 1))}>Next</button></div></footer>
  </div>;
}

function OrganizationPage({ organizationName, companies, company, onSelectCompany, onCompanySaved, branches, positions, request, submit, busy, onRefresh }: { organizationName: string; companies: Company[]; company: Company | null; onSelectCompany: (id: string) => void; onCompanySaved: (company: Company) => void; branches: Branch[]; positions: Position[]; request: <T>(path: string, init?: RequestInit) => Promise<T>; submit: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean; onRefresh: () => void }) {
  const [orgView, setOrgView] = useState<'chart' | 'details'>('chart');
  const [showCompanyForm, setShowCompanyForm] = useState(false); const [newCompanyDraft, setNewCompanyDraft] = useState<CompanyDraft>(emptyCompanyDraft); const [companyDraft, setCompanyDraft] = useState<CompanyDraft>(emptyCompanyDraft); const [companySaving, setCompanySaving] = useState(false); const [companyNotice, setCompanyNotice] = useState('');
  const [branchCode, setBranchCode] = useState(''); const [branchName, setBranchName] = useState(''); const [positionCode, setPositionCode] = useState(''); const [positionName, setPositionName] = useState('');
  const [companyError, setCompanyError] = useState('');
  useEffect(() => { setCompanyDraft(company ? companyDraftFrom(company) : emptyCompanyDraft); setCompanyNotice(''); setCompanyError(''); }, [company?.id]);
  const companyPath = company ? `/api/v1/companies/${company.id}/branches` : '';
  async function createCompany(event: FormEvent) { event.preventDefault(); setCompanyError(''); setCompanySaving(true); try { const created = await request<Company>('/api/v1/companies', { method: 'POST', body: JSON.stringify(newCompanyDraft) }); onCompanySaved(created); setNewCompanyDraft(emptyCompanyDraft); setShowCompanyForm(false); } catch (error) { setCompanyError(error instanceof Error ? error.message : 'Could not create legal entity.'); } finally { setCompanySaving(false); } }
  async function saveCompany(event: FormEvent) { event.preventDefault(); if (!company) return; setCompanySaving(true); setCompanyError(''); setCompanyNotice(''); try { const updated = await request<Company>(`/api/v1/companies/${company.id}`, { method: 'PUT', body: JSON.stringify(companyDraft) }); onCompanySaved(updated); setCompanyNotice('Legal entity details saved.'); } catch (error) { setCompanyError(error instanceof Error ? error.message : 'Could not save legal entity details.'); } finally { setCompanySaving(false); } }
  return <div className="org-page"><nav className="org-page-tabs" aria-label="Organization pages"><button type="button" className={orgView==='chart'?'active':''} onClick={()=>setOrgView('chart')}>Organization chart</button><button type="button" className={orgView==='details'?'active':''} onClick={()=>setOrgView('details')}>Company setup &amp; positions</button></nav>{orgView==='chart'?<OrganizationChart company={company} companies={companies} onSelectCompany={onSelectCompany} request={request}/>:<div className="org-maintenance"><section className="people-card org-root-card"><div className="people-card-heading"><div><p className="eyebrow">ORGANIZATION</p><h2>{organizationName}</h2><p>Maintain legal entities, company details, branches, and positions.</p></div><button type="button" className="security-submit" onClick={() => { setShowCompanyForm(value => !value); setCompanyError(''); }}>＋ Add legal entity</button></div>
      {showCompanyForm && <form className="org-company-form" onSubmit={event => void createCompany(event)}><div className="org-form-grid"><Field label="Company code"><input value={newCompanyDraft.companyCode} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, companyCode: event.target.value })} required maxLength={40} pattern="[A-Za-z0-9_-]+" placeholder="MAIN" /></Field><Field label="Registered legal name"><input value={newCompanyDraft.legalName} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, legalName: event.target.value })} required maxLength={200} placeholder="Legal entity name" /></Field><Field label="Owner / representative"><input value={newCompanyDraft.ownerName} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, ownerName: event.target.value })} maxLength={200} /></Field><Field label="Owner email"><input type="email" value={newCompanyDraft.ownerEmail} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, ownerEmail: event.target.value })} maxLength={254} /></Field><Field label="Phone"><input type="tel" value={newCompanyDraft.ownerPhone} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, ownerPhone: event.target.value })} maxLength={40} /></Field><Field label="City"><input value={newCompanyDraft.city} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, city: event.target.value })} maxLength={120} /></Field><Field label="Region / province"><input value={newCompanyDraft.region} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, region: event.target.value })} maxLength={120} /></Field><Field label="Country code"><input value={newCompanyDraft.countryCode} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, countryCode: event.target.value.toUpperCase() })} required maxLength={2} pattern="[A-Z]{2}" placeholder="PH" /></Field></div><details className="org-extra-details"><summary>More legal and address details</summary><div className="org-form-grid"><Field label="Trade name"><input value={newCompanyDraft.tradeName} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, tradeName: event.target.value })} maxLength={200} /></Field><Field label="Entity type"><select value={newCompanyDraft.entityType} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, entityType: event.target.value })}><option value="">Select type</option><option value="CORPORATION">Corporation</option><option value="SOLE_PROPRIETORSHIP">Sole proprietorship</option><option value="PARTNERSHIP">Partnership</option><option value="NONPROFIT">Nonprofit</option><option value="OTHER">Other</option></select></Field><Field label="Registration number"><input value={newCompanyDraft.registrationNumber} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, registrationNumber: event.target.value })} maxLength={100} /></Field><Field label="Industry"><input value={newCompanyDraft.industry} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, industry: event.target.value })} maxLength={120} /></Field><Field label="Address line 1"><input value={newCompanyDraft.addressLine1} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, addressLine1: event.target.value })} maxLength={200} /></Field><Field label="Address line 2"><input value={newCompanyDraft.addressLine2} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, addressLine2: event.target.value })} maxLength={200} /></Field><Field label="Postal code"><input value={newCompanyDraft.postalCode} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, postalCode: event.target.value })} maxLength={20} /></Field><Field label="Time zone"><input value={newCompanyDraft.timezone} onChange={event => setNewCompanyDraft({ ...newCompanyDraft, timezone: event.target.value })} required maxLength={64} /></Field></div></details><div className="org-form-actions"><button type="submit" className="security-submit" disabled={companySaving}>{companySaving ? 'Creating…' : 'Create company'}</button></div>{companyError && <p className="platform-alert" role="alert">{companyError}</p>}</form>}
      <div className="org-company-list" role="list" aria-label="Legal entities">{companies.map(item => <button type="button" role="listitem" key={item.id} className={`org-company-item${company?.id === item.id ? ' selected' : ''}`} onClick={() => onSelectCompany(item.id)}><span className="org-company-icon">▦</span><span><strong>{item.legalName}</strong><small>{item.companyCode} · {item.countryCode} · {item.timezone}</small></span><span className="org-company-arrow">→</span></button>)}{!companies.length && <p className="people-muted">No legal entities yet. Add your first company to begin building the organization.</p>}</div>
    </section>
    {company && <><section className="people-card org-company-detail"><div className="people-card-heading"><div><p className="eyebrow">LEGAL ENTITY · {company.companyCode}</p><h2>{company.legalName}</h2><p>Maintain company registration, ownership, and registered address details.</p></div></div>
      <form className="org-entity-details" onSubmit={event => void saveCompany(event)}><div className="org-detail-section"><h3>Legal identity</h3><div className="org-form-grid"><Field label="Company code"><input value={companyDraft.companyCode} onChange={event => setCompanyDraft({ ...companyDraft, companyCode: event.target.value })} required maxLength={40} pattern="[A-Za-z0-9_-]+" /></Field><Field label="Registered legal name"><input value={companyDraft.legalName} onChange={event => setCompanyDraft({ ...companyDraft, legalName: event.target.value })} required maxLength={200} /></Field><Field label="Trade name"><input value={companyDraft.tradeName} onChange={event => setCompanyDraft({ ...companyDraft, tradeName: event.target.value })} maxLength={200} /></Field><Field label="Entity type"><select value={companyDraft.entityType} onChange={event => setCompanyDraft({ ...companyDraft, entityType: event.target.value })}><option value="">Select type</option><option value="CORPORATION">Corporation</option><option value="SOLE_PROPRIETORSHIP">Sole proprietorship</option><option value="PARTNERSHIP">Partnership</option><option value="NONPROFIT">Nonprofit</option><option value="OTHER">Other</option></select></Field><Field label="Registration number"><input value={companyDraft.registrationNumber} onChange={event => setCompanyDraft({ ...companyDraft, registrationNumber: event.target.value })} maxLength={100} /></Field><Field label="Industry"><input value={companyDraft.industry} onChange={event => setCompanyDraft({ ...companyDraft, industry: event.target.value })} maxLength={120} /></Field></div></div><div className="org-detail-section"><h3>Owner &amp; contact</h3><div className="org-form-grid"><Field label="Owner / representative"><input value={companyDraft.ownerName} onChange={event => setCompanyDraft({ ...companyDraft, ownerName: event.target.value })} maxLength={200} /></Field><Field label="Owner email"><input type="email" value={companyDraft.ownerEmail} onChange={event => setCompanyDraft({ ...companyDraft, ownerEmail: event.target.value })} maxLength={254} /></Field><Field label="Phone"><input type="tel" value={companyDraft.ownerPhone} onChange={event => setCompanyDraft({ ...companyDraft, ownerPhone: event.target.value })} maxLength={40} /></Field></div></div><div className="org-detail-section"><h3>Registered location</h3><div className="org-form-grid"><Field label="Address line 1"><input value={companyDraft.addressLine1} onChange={event => setCompanyDraft({ ...companyDraft, addressLine1: event.target.value })} maxLength={200} /></Field><Field label="Address line 2"><input value={companyDraft.addressLine2} onChange={event => setCompanyDraft({ ...companyDraft, addressLine2: event.target.value })} maxLength={200} /></Field><Field label="City"><input value={companyDraft.city} onChange={event => setCompanyDraft({ ...companyDraft, city: event.target.value })} maxLength={120} /></Field><Field label="Region / province"><input value={companyDraft.region} onChange={event => setCompanyDraft({ ...companyDraft, region: event.target.value })} maxLength={120} /></Field><Field label="Postal code"><input value={companyDraft.postalCode} onChange={event => setCompanyDraft({ ...companyDraft, postalCode: event.target.value })} maxLength={20} /></Field><Field label="Country code"><input value={companyDraft.countryCode} onChange={event => setCompanyDraft({ ...companyDraft, countryCode: event.target.value.toUpperCase() })} required maxLength={2} pattern="[A-Z]{2}" /></Field><Field label="Time zone"><input value={companyDraft.timezone} onChange={event => setCompanyDraft({ ...companyDraft, timezone: event.target.value })} required maxLength={64} /></Field></div></div><div className="org-entity-save">{companyError && <p className="platform-alert" role="alert">{companyError}</p>}{companyNotice && <p className="platform-notice" role="status">{companyNotice}</p>}<button type="submit" className="security-submit" disabled={companySaving}>{companySaving ? 'Saving…' : 'Save legal entity'}</button></div></form>
    </section><section className="people-card org-supporting-card"><div className="people-card-heading"><div><p className="eyebrow">SUPPORTING SETUP</p><h2>Branches &amp; positions</h2><p>Manage work locations and job titles. Departments and sections are maintained in the Organization chart.</p></div></div><div className="people-org-columns">
      <div className="people-org-section"><h3>Branches</h3><form className="people-inline-form" onSubmit={event => void submit(event, () => request(companyPath, { method: 'POST', body: JSON.stringify({ branchCode, branchName }) }), 'Branch added.') }><Field label="Code"><input value={branchCode} onChange={event => setBranchCode(event.target.value)} required maxLength={40} pattern="[A-Za-z0-9_-]+" /></Field><Field label="Branch name"><input value={branchName} onChange={event => setBranchName(event.target.value)} required maxLength={200} /></Field><button className="session-revoke" type="submit" disabled={busy}>Add branch</button></form><RecordList items={branches.map(item => ({ id: item.id, title: item.branchName, meta: `${item.branchCode}${item.regionCode ? ` · ${item.regionCode}` : ''}` }))} empty="No branches configured." /></div>
      <div className="people-org-section"><h3>Positions</h3><form className="people-inline-form" onSubmit={event => void submit(event, () => request('/api/v1/personnel/positions', { method: 'POST', body: JSON.stringify({ companyId: company.id, code: positionCode, name: positionName }) }), 'Position added.') }><Field label="Code"><input value={positionCode} onChange={event => setPositionCode(event.target.value)} required maxLength={40} pattern="[A-Za-z0-9_-]+" /></Field><Field label="Position title"><input value={positionName} onChange={event => setPositionName(event.target.value)} required maxLength={160} /></Field><button className="session-revoke" type="submit" disabled={busy}>Add position</button></form><div className="people-record-list">{positions.map(item => <div className="people-record" key={item.id}><span><strong>{item.name}</strong><small>{item.code}{item.active ? '' : ' · Inactive'}</small></span><button type="button" className="session-revoke" onClick={() => void request(`/api/v1/personnel/positions/${item.id}/status`, { method: 'PATCH', body: JSON.stringify({ active: !item.active }) }).then(onRefresh)}>{item.active ? 'Deactivate' : 'Reactivate'}</button></div>)}{!positions.length && <p className="people-muted">No positions configured.</p>}</div></div>
    </div></section></>}
  </div>}</div>;
}

function RehirePolicyPage({ request, submit, busy }: { request: <T>(path: string, init?: RequestInit) => Promise<T>; submit: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [enabled, setEnabled] = useState(true); const [days, setDays] = useState('0'); const [loaded, setLoaded] = useState(false);
  useEffect(() => { request<{ enabled: boolean; minimumWaitDays: number }>('/api/v1/personnel/rehire-policy').then(policy => { setEnabled(policy.enabled); setDays(String(policy.minimumWaitDays)); setLoaded(true); }).catch(() => setLoaded(true)); }, []);
  return <section className="people-card people-policy-card"><p className="eyebrow">LIFECYCLE POLICY</p><h2>Rehire eligibility</h2><p>Control when a separated employee can be submitted for rehire.</p>{loaded ? <form className="people-policy-form" onSubmit={event => void submit(event, () => request('/api/v1/personnel/rehire-policy', { method: 'PUT', body: JSON.stringify({ enabled, minimumWaitDays: Number(days) }) }), 'Rehire policy saved.') }><label className="people-toggle"><input type="checkbox" checked={enabled} onChange={event => setEnabled(event.target.checked)} /><span><strong>Allow rehire requests</strong><small>When disabled, new rehire requests are blocked.</small></span></label><Field label="Minimum waiting period (days)"><input type="number" min="0" max="3650" value={days} onChange={event => setDays(event.target.value)} disabled={!enabled} /></Field><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Save policy'}</button></form> : <p className="people-muted">Loading policy…</p>}</section>;
}

function EmployeeWorkspace({ employee, company, employees, departments, positions, branches, canHr, canPayroll, currentUserId, request, onBack, initialTab = 'Profile' }: { employee: Employee; company: Company; employees: Employee[]; departments: Department[]; positions: Position[]; branches: Branch[]; canHr: boolean; canPayroll: boolean; currentUserId: string; request: <T>(path: string, init?: RequestInit) => Promise<T>; onBack: () => void; initialTab?: string }) {
  const [profile, setProfile] = useState<Profile | null>(null); const [activeTab, setActiveTab] = useState(initialTab); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [busy, setBusy] = useState(false);
  const tabs = ['Profile', 'Assignments', 'Employment', ...(canPayroll ? ['Compensation'] : []), 'Private data', 'Documents', 'HR lifecycle'];
  useEffect(() => { setProfile(null); setActiveTab(initialTab); setError(''); setNotice(''); }, [employee.id, initialTab]);
  useEffect(() => { request<Profile>(`/api/v1/personnel/employees/${employee.id}/profile`).then(setProfile).catch(reason => setError(reason instanceof Error ? reason.message : 'Could not load employee profile.')); }, [employee.id]);
  async function save(event: FormEvent, action: () => Promise<unknown>, message: string) { event.preventDefault(); setBusy(true); setError(''); setNotice(''); try { await action(); setNotice(message); } catch (e) { setError(e instanceof Error ? e.message : 'Could not save this change.'); } finally { setBusy(false); } }
  const displayName = `${profile?.preferredName || employee.firstName} ${employee.lastName}`;
  const departmentName = departments.find(item => item.id === (profile?.departmentId || employee.departmentId))?.name || employee.departmentName || 'Not assigned';
  const positionName = positions.find(item => item.id === employee.positionId)?.name || employee.positionName || 'Not assigned';
  const branchName = branches.find(item => item.id === profile?.branchId)?.branchName || 'Not assigned';
  const tenure = (() => { const start = new Date(`${employee.hireDate}T12:00:00`); const now = new Date(); let months = (now.getFullYear() - start.getFullYear()) * 12 + now.getMonth() - start.getMonth(); if (now.getDate() < start.getDate()) months -= 1; if (!Number.isFinite(months) || months < 0) return '—'; const years = Math.floor(months / 12); const remainder = months % 12; return years ? `${years}y ${remainder}m` : `${remainder}m`; })();
  return <section className="employee-profile-layout">
    <aside className="people-card employee-summary-card">
      <div className="employee-summary-person">{profile?.photoDataUrl || employee.photoDataUrl ? <img className="employee-summary-avatar" src={profile?.photoDataUrl || employee.photoDataUrl || ''} alt={`${displayName} profile`} /> : <span className="employee-summary-avatar">{employee.firstName.slice(0, 1)}{employee.lastName.slice(0, 1)}</span>}<h2>{displayName}</h2><p>{positionName}</p><div className="employee-summary-badges"><span>{employee.employmentStatus.replaceAll('_', ' ')}</span><span>{profile?.employmentType?.replaceAll('_', ' ') || 'Employee'}</span></div></div>
      <div className="employee-summary-facts"><SummaryLine label="Employee no." value={employee.employeeNumber} /><SummaryLine label="Department" value={departmentName} /><SummaryLine label="Work location" value={branchName} /><SummaryLine label="Hired" value={new Date(`${employee.hireDate}T12:00:00`).toLocaleDateString()} /><SummaryLine label="Tenure" value={tenure} /></div>
      <div className="employee-summary-shortcuts"><button type="button" onClick={() => setActiveTab('Assignments')}>Assignments</button><button type="button" onClick={() => setActiveTab('Employment')}>Employment history</button></div>
    </aside>
    <div className="people-card employee-profile-main">
      <button type="button" className="people-back" onClick={onBack}>← People directory</button>
      {error && <div className="platform-alert" role="alert">{error}</div>}{notice && <p className="platform-notice" role="status">{notice}</p>}
      <nav className="people-profile-tabs" aria-label="Employee profile sections">{tabs.map(item => <button key={item} type="button" className={activeTab === item ? 'active' : ''} onClick={() => { setActiveTab(item); setError(''); setNotice(''); }}>{item}</button>)}</nav>
      {!profile ? <p className="people-muted">Loading profile…</p> : activeTab === 'Profile' ? <ProfileEditor key={profile.id} profile={profile} employees={employees} canHr={canHr} request={request} save={save} busy={busy} onProfile={setProfile} />
      : activeTab === 'Assignments' ? <AssignmentsPanel employee={employee} company={company} departments={departments} positions={positions} branches={branches} request={request} save={save} busy={busy} />
      : activeTab === 'Employment' ? <EmploymentPanel employee={employee} request={request} save={save} busy={busy} />
      : activeTab === 'Compensation' ? <CompensationPanel employee={employee} request={request} save={save} busy={busy} />
      : activeTab === 'Private data' ? <PrivateDataPanel employee={employee} request={request} save={save} busy={busy} />
      : activeTab === 'Documents' ? <DocumentsPanel employee={employee} request={request} save={save} busy={busy} />
      : <LifecyclePanel employee={employee} currentUserId={currentUserId} request={request} save={save} busy={busy} />}
    </div>
  </section>;
}

function ProfileEditor({ profile, employees, canHr, request, save, busy, onProfile }: { profile: Profile; employees: Employee[]; canHr: boolean; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean; onProfile: (profile: Profile) => void }) {
  const [middle, setMiddle] = useState(profile.middleName || ''); const [preferred, setPreferred] = useState(profile.preferredName || ''); const [suffix, setSuffix] = useState(profile.suffix || ''); const [supervisor, setSupervisor] = useState(''); const [photo, setPhoto] = useState<string | null>(profile.photoDataUrl); const [photoChanged, setPhotoChanged] = useState(false); const [photoError, setPhotoError] = useState('');
  const base = `/api/v1/personnel/employees/${profile.id}`;
  return <div className="people-detail-grid"><form className="people-subcard people-form" onSubmit={event => void save(event, async () => { const updated = await request<Profile>(`${base}/profile`, { method: 'PATCH', body: JSON.stringify({ middleName: middle, preferredName: preferred, suffix }) }); const saved = photoChanged ? await request<Profile>(`${base}/profile/photo`, { method: 'PUT', body: JSON.stringify({ photoDataUrl: photo }) }) : updated; onProfile(saved); setPhotoChanged(false); }, 'Profile details saved.') }><div><h3>Personal profile</h3><p>Directory profile fields. Sensitive identifiers are stored separately.</p></div><div className="people-photo-editor">{photo ? <img src={photo} alt="Employee profile preview" /> : <span>{profile.firstName.slice(0, 1)}{profile.lastName.slice(0, 1)}</span>}<div><Field label="Employee photo"><input type="file" accept="image/png,image/jpeg,image/webp" disabled={!canHr} onChange={event => { const file = event.currentTarget.files?.[0]; event.currentTarget.value = ''; if (!file) return; setPhotoError(''); void prepareEmployeePhoto(file).then(value => { setPhoto(value); setPhotoChanged(true); }).catch(reason => setPhotoError(reason instanceof Error ? reason.message : 'Could not prepare the photo.')); }} /></Field><small>PNG, JPG, or WebP. The photo is resized before saving and appears in the directory and organization chart.</small>{photo && canHr && <button type="button" className="session-revoke" onClick={() => { setPhoto(null); setPhotoChanged(true); }}>Remove photo</button>}{photoError && <span className="field-error">{photoError}</span>}</div></div><div className="people-readonly-grid"><Field label="First name"><input value={profile.firstName} readOnly /></Field><Field label="Last name"><input value={profile.lastName} readOnly /></Field><Field label="Employee number"><input value={profile.employeeNumber} readOnly /></Field><Field label="Hire date"><input value={profile.hireDate} readOnly /></Field></div><Field label="Middle name"><input value={middle} onChange={event => setMiddle(event.target.value)} maxLength={120} disabled={!canHr} /></Field><Field label="Preferred name"><input value={preferred} onChange={event => setPreferred(event.target.value)} maxLength={120} disabled={!canHr} /></Field><Field label="Suffix"><input value={suffix} onChange={event => setSuffix(event.target.value)} maxLength={30} disabled={!canHr} /></Field>{canHr && <button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Save profile'}</button>}</form><div className="people-subcard"><h3>Employment summary</h3><SummaryLine label="Status" value={profile.employmentStatus.replaceAll('_', ' ')} /><SummaryLine label="Type" value={profile.employmentType.replaceAll('_', ' ')} /><SummaryLine label="Department" value={profile.departmentId || 'Not assigned'} /><SummaryLine label="Reporting to" value={supervisor || 'Choose a supervisor below'} />{canHr && <form className="people-form people-supervisor-form" onSubmit={event => void save(event, () => request(`${base}/supervisor`, { method: 'PUT', body: JSON.stringify({ supervisorId: supervisor || null }) }), 'Reporting line updated.') }><Field label="Supervisor"><select value={supervisor} onChange={event => setSupervisor(event.target.value)}><option value="">No supervisor</option>{employees.filter(item => item.id !== profile.id && item.employmentStatus === 'ACTIVE').map(item => <option key={item.id} value={item.id}>{item.firstName} {item.lastName} · {item.employeeNumber}</option>)}</select></Field><button className="session-revoke" type="submit" disabled={busy}>Save supervisor</button><small>The API validates company scope and prevents reporting cycles.</small></form>}</div></div>;
}

function AssignmentsPanel({ employee, company, departments, positions, branches, request, save, busy }: { employee: Employee; company: Company; departments: Department[]; positions: Position[]; branches: Branch[]; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [rows, setRows] = useState<Assignment[]>([]); const [branch, setBranch] = useState(''); const [department, setDepartment] = useState(''); const [position, setPosition] = useState(''); const [effectiveDate, setDate] = useState(dateToday()); const [reason, setReason] = useState(''); const path = `/api/v1/personnel/employees/${employee.id}/assignments`;
  useEffect(() => { request<Assignment[]>(path).then(setRows).catch(() => setRows([])); }, [employee.id]);
  return <div className="people-detail-grid"><section className="people-subcard"><h3>Assignment history</h3>{rows.length ? <div className="people-record-list">{rows.map(row => <div className="people-record" key={row.id}><span><strong>{new Date(`${row.effectiveDate}T12:00:00`).toLocaleDateString()}</strong><small>{[branches.find(item => item.id === row.branchId)?.branchName, departments.find(item => item.id === row.departmentId)?.name, positions.find(item => item.id === row.positionId)?.name].filter(Boolean).join(' · ') || 'No role assignment'} · {row.reason}</small></span></div>)}</div> : <p className="people-muted">No assignment history recorded.</p>}</section><form className="people-subcard people-form" onSubmit={event => void save(event, async () => { const result = await request<Assignment>(path, { method: 'POST', body: JSON.stringify({ companyId: company.id, branchId: branch || null, departmentId: department || null, positionId: position || null, effectiveDate, reason }) }); setRows([result, ...rows]); }, 'Assignment recorded.') }><h3>Record assignment</h3><p>Assignment changes are effective dated and must follow the previous assignment.</p><Field label="Branch"><select value={branch} onChange={event => setBranch(event.target.value)}><option value="">No branch</option>{branches.map(item => <option key={item.id} value={item.id}>{item.branchName}</option>)}</select></Field><Field label="Department"><select value={department} onChange={event => setDepartment(event.target.value)}><option value="">No department</option>{departments.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Position"><select value={position} onChange={event => setPosition(event.target.value)}><option value="">No position</option>{positions.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Effective date"><input type="date" value={effectiveDate} max={dateToday()} onChange={event => setDate(event.target.value)} required /></Field><Field label="Reason"><textarea value={reason} onChange={event => setReason(event.target.value)} maxLength={250} required /></Field><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Save assignment'}</button></form></div>;
}

function EmploymentPanel({ employee, request, save, busy }: { employee: Employee; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [rows, setRows] = useState<EmploymentEvent[]>([]); const [status, setStatus] = useState('ACTIVE'); const [type, setType] = useState('REGULAR'); const [date, setDate] = useState(dateToday()); const [title, setTitle] = useState(''); const [reason, setReason] = useState(''); const path = `/api/v1/personnel/employees/${employee.id}/employment`;
  useEffect(() => { request<EmploymentEvent[]>(path).then(setRows).catch(() => setRows([])); }, [employee.id]);
  return <div className="people-detail-grid"><RecordTimeline title="Employment history" rows={rows.map(row => ({ id: row.id, date: row.effectiveDate, title: `${row.employmentStatus.replaceAll('_', ' ')} · ${row.employmentType.replaceAll('_', ' ')}`, detail: `${row.jobTitle || 'No job title'} · ${row.reason}` }))} /><form className="people-subcard people-form" onSubmit={event => void save(event, async () => { const result = await request<EmploymentEvent>(path, { method: 'POST', body: JSON.stringify({ effectiveDate: date, status, type, jobTitle: title || null, reason }) }); setRows([result, ...rows]); }, 'Employment change recorded.') }><h3>Record employment change</h3><p>Transitions and effective dates are validated by the HR workflow.</p><Field label="Effective date"><input type="date" value={date} max={dateToday()} onChange={event => setDate(event.target.value)} required /></Field><Field label="Employment status"><select value={status} onChange={event => setStatus(event.target.value)}>{employmentStatuses.map(item => <option key={item}>{item}</option>)}</select></Field><Field label="Employment type"><select value={type} onChange={event => setType(event.target.value)}>{employmentTypes.map(item => <option key={item}>{item}</option>)}</select></Field><Field label="Job title"><input value={title} onChange={event => setTitle(event.target.value)} maxLength={160} /></Field><Field label="Reason"><textarea value={reason} onChange={event => setReason(event.target.value)} maxLength={250} required /></Field><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Record change'}</button></form></div>;
}

function CompensationPanel({ employee, request, save, busy }: { employee: Employee; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [rows, setRows] = useState<Compensation[]>([]); const [date, setDate] = useState(dateToday()); const [amount, setAmount] = useState(''); const [basis, setBasis] = useState('MONTHLY'); const [reason, setReason] = useState(''); const path = `/api/v1/personnel/employees/${employee.id}/compensation`;
  useEffect(() => { request<Compensation[]>(path).then(setRows).catch(() => setRows([])); }, [employee.id]);
  return <div className="people-detail-grid"><section className="people-subcard"><h3>Compensation history</h3><p className="people-sensitive-note">Restricted to workspace owners and payroll officers.</p><div className="people-record-list">{rows.map(row => <div className="people-record" key={row.id}><span><strong>{new Intl.NumberFormat(undefined, { style: 'currency', currency: row.currencyCode }).format(row.amount)} / {row.payBasis.toLowerCase()}</strong><small>Effective {new Date(`${row.effectiveDate}T12:00:00`).toLocaleDateString()} · {row.reason}</small></span></div>)}{!rows.length && <p className="people-muted">No compensation history recorded.</p>}</div></section><form className="people-subcard people-form" onSubmit={event => void save(event, async () => { const item = await request<Compensation>(path, { method: 'POST', body: JSON.stringify({ effectiveDate: date, amount: Number(amount), payBasis: basis, reason }) }); setRows([item, ...rows]); }, 'Compensation entry recorded.') }><h3>Record compensation</h3><p>Entries are append-only and effective dates must follow previous entries.</p><Field label="Effective date"><input type="date" value={date} max={dateToday()} onChange={event => setDate(event.target.value)} required /></Field><Field label="Amount (PHP)"><input type="number" min="0.01" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} required /></Field><Field label="Pay basis"><select value={basis} onChange={event => setBasis(event.target.value)}><option>MONTHLY</option><option>DAILY</option><option>HOURLY</option></select></Field><Field label="Reason"><textarea value={reason} onChange={event => setReason(event.target.value)} maxLength={250} required /></Field><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Add compensation'}</button></form></div>;
}

function PrivateDataPanel({ employee, request, save, busy }: { employee: Employee; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [data, setData] = useState<PrivateData>({ governmentId: '', contactEmail: '', mobile: '', bankAccount: '' }); const path = `/api/v1/personnel/employees/${employee.id}/private`;
  useEffect(() => { request<PrivateData>(path).then(item => setData({ governmentId: item.governmentId || '', contactEmail: item.contactEmail || '', mobile: item.mobile || '', bankAccount: item.bankAccount || '' })).catch(() => setData({ governmentId: '', contactEmail: '', mobile: '', bankAccount: '' })); }, [employee.id]);
  return <form className="people-subcard people-private-form" onSubmit={event => void save(event, () => request(path, { method: 'PUT', body: JSON.stringify(data) }), 'Encrypted private employee data saved.') }><p className="eyebrow">RESTRICTED EMPLOYEE DATA</p><h3>Private contact &amp; payment details</h3><p>This information is encrypted at rest and excluded from normal directory responses. Only authorized HR users should access it.</p><div className="people-readonly-grid"><Field label="Government ID"><input autoComplete="off" value={data.governmentId || ''} onChange={event => setData({ ...data, governmentId: event.target.value })} maxLength={100} /></Field><Field label="Contact email"><input type="email" autoComplete="off" value={data.contactEmail || ''} onChange={event => setData({ ...data, contactEmail: event.target.value })} maxLength={254} /></Field><Field label="Mobile"><input autoComplete="off" value={data.mobile || ''} onChange={event => setData({ ...data, mobile: event.target.value })} maxLength={40} /></Field><Field label="Bank account"><input autoComplete="off" value={data.bankAccount || ''} onChange={event => setData({ ...data, bankAccount: event.target.value })} maxLength={100} /></Field></div><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Save private data'}</button></form>;
}

function DocumentsPanel({ employee, request, save, busy }: { employee: Employee; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [rows, setRows] = useState<Document[]>([]); const [file, setFile] = useState<File | null>(null); const [category, setCategory] = useState('CONTRACT'); const [lifecycle, setLifecycle] = useState<Record<string, { legalHold: boolean; retainUntil: string | null; deleted: boolean }>>({}); const base = `/api/v1/personnel/employees/${employee.id}/documents`;
  async function load() { const docs = await request<Document[]>(base); setRows(docs); const entries = await Promise.all(docs.map(async doc => { try { return [doc.id, await request<{ legalHold: boolean; retainUntil: string | null; deleted: boolean }>(`${base}/${doc.id}/lifecycle`)] as const; } catch { return [doc.id, { legalHold: false, retainUntil: null, deleted: false }] as const; } })); setLifecycle(Object.fromEntries(entries)); }
  useEffect(() => { void load().catch(() => setRows([])); }, [employee.id]);
  return <div className="people-documents"><form className="people-subcard people-form" onSubmit={event => void save(event, async () => { if (!file) throw new Error('Choose a PDF document.'); const body = new FormData(); body.append('file', file); body.append('category', category); await request(`${base}/upload`, { method: 'POST', body }); setFile(null); await load(); }, 'Document uploaded to encrypted quarantine for review.') }><p className="eyebrow">DOCUMENT INTAKE</p><h3>Upload employee document</h3><p>PDF files are encrypted at rest and quarantined until scanned and independently reviewed. Maximum upload size is 2 MiB.</p><Field label="Category"><select value={category} onChange={event => setCategory(event.target.value)}>{documentCategories.filter(item => item !== 'IDENTITY').map(item => <option key={item}>{item}</option>)}</select></Field><Field label="PDF file"><input type="file" accept="application/pdf,.pdf" onChange={event => setFile(event.target.files?.[0] || null)} required /></Field><button className="security-submit" type="submit" disabled={busy || !file}>{busy ? 'Uploading…' : 'Upload document'}</button></form><section className="people-subcard"><h3>Document register</h3>{rows.length ? <div className="people-record-list">{rows.map(doc => <DocumentRecord key={doc.id} employeeId={employee.id} document={doc} lifecycle={lifecycle[doc.id]} request={request} onRefresh={() => void load()} />)}</div> : <p className="people-muted">No documents registered.</p>}</section></div>;
}

function DocumentRecord({ employeeId, document: doc, lifecycle, request, onRefresh }: { employeeId: string; document: Document; lifecycle?: { legalHold: boolean; retainUntil: string | null; deleted: boolean }; request: <T>(path: string, init?: RequestInit) => Promise<T>; onRefresh: () => void }) {
  const [scan, setScan] = useState(''); const [retention, setRetention] = useState(lifecycle?.retainUntil || ''); const [hold, setHold] = useState(lifecycle?.legalHold || false); const [busy, setBusy] = useState(false); const base = `/api/v1/personnel/employees/${employeeId}/documents/${doc.id}`;
  useEffect(() => { setRetention(lifecycle?.retainUntil || ''); setHold(lifecycle?.legalHold || false); }, [lifecycle?.retainUntil, lifecycle?.legalHold]);
  async function run(action: () => Promise<unknown>) { setBusy(true); try { await action(); onRefresh(); } finally { setBusy(false); } }
  return <article className="people-document-record"><div className="people-record"><span><strong>{doc.filename}</strong><small>{doc.category} · {(doc.sizeBytes / 1024).toFixed(0)} KB · v{doc.version}{doc.expiresOn ? ` · Expires ${doc.expiresOn}` : ''}</small><code>{doc.sha256}</code></span>{!lifecycle?.deleted && <a className="platform-text-action" href={`${base}/content`} onClick={async event => { event.preventDefault(); const response = await fetch(`${base}/content`, { headers: { Authorization: `Bearer ${sessionStorage.getItem('apexHrm.accessToken') || ''}` } }); if (response.ok) { const blob = await response.blob(); const link = window.document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = doc.filename; link.click(); URL.revokeObjectURL(link.href); } }}>Download</a>}</div>
    {lifecycle && <div className="people-document-actions"><span className={`platform-status-tag ${lifecycle.deleted ? 'suspended' : lifecycle.legalHold ? 'closed' : 'active'}`}>{lifecycle.deleted ? 'TOMBSTONED' : lifecycle.legalHold ? 'LEGAL HOLD' : 'RETAINED'}</span><Field label="Retention until"><input type="date" min={dateToday()} value={retention} onChange={event => setRetention(event.target.value)} /></Field><button type="button" className="session-revoke" disabled={busy || !retention || lifecycle.deleted} onClick={() => void run(() => request(`${base}/retention`, { method: 'PUT', body: JSON.stringify({ retainUntil: retention }) }))}>Extend retention</button><label className="people-toggle people-compact-toggle"><input type="checkbox" checked={hold} disabled={busy || lifecycle.deleted} onChange={event => setHold(event.target.checked)} /><span>Legal hold</span></label><button type="button" className="session-revoke" disabled={busy || lifecycle.deleted} onClick={() => void run(() => request(`${base}/hold`, { method: 'PUT', body: JSON.stringify({ enabled: hold, reason: hold ? 'Administrative retention hold' : '' }) }))}>Save hold</button><button type="button" className="session-revoke" disabled={busy || lifecycle.deleted} onClick={() => void run(() => request(`${base}/scan`, { method: 'POST' }).then(result => setScan(String(result))))}>Scan</button><Field label="Review retain until"><input type="date" min={dateToday()} value={retention} onChange={event => setRetention(event.target.value)} /></Field><button type="button" className="session-revoke" disabled={busy || lifecycle.deleted || !scan} onClick={() => void run(() => request(`${base}/review`, { method: 'POST', body: JSON.stringify({ status: 'RELEASED', retainUntil: retention || null }) }))}>Release clean file</button><button type="button" className="session-revoke" disabled={busy || lifecycle.deleted || !scan} onClick={() => void run(() => request(`${base}/review`, { method: 'POST', body: JSON.stringify({ status: 'REJECTED', retainUntil: retention || null }) }))}>Reject</button></div>}{scan && <small className="people-muted">Latest scan: {scan}</small>}</article>;
}

function LifecyclePanel({ employee, currentUserId, request, save, busy }: { employee: Employee; currentUserId: string; request: <T>(path: string, init?: RequestInit) => Promise<T>; save: (event: FormEvent, action: () => Promise<unknown>, message: string) => Promise<void>; busy: boolean }) {
  const [cases, setCases] = useState<HrCase[]>([]); const [type, setType] = useState('ONBOARDING'); const [date, setDate] = useState(dateToday()); const [reason, setReason] = useState(''); const [requirements, setRequirements] = useState<Requirement[]>([]); const [clearances, setClearances] = useState<Clearance[]>([]); const [assets, setAssets] = useState<Asset[]>([]); const [rehire, setRehire] = useState<Rehire[]>([]); const [selectedCase, setSelectedCase] = useState(''); const [assetTag, setAssetTag] = useState(''); const [assetDescription, setAssetDescription] = useState('');
  const base = `/api/v1/personnel/employees/${employee.id}`;
  async function loadCases() { const list = await request<HrCase[]>(`${base}/hr-cases`); setCases(list); const open = list.find(item => item.status === 'PENDING'); if (open) { setSelectedCase(open.id); if (open.type === 'ONBOARDING') request<Requirement[]>(`${base}/hr-cases/${open.id}/requirements`).then(setRequirements).catch(() => setRequirements([])); else { request<Clearance[]>(`${base}/hr-cases/${open.id}/clearances`).then(setClearances).catch(() => setClearances([])); request<Asset[]>(`${base}/hr-cases/${open.id}/assets`).then(setAssets).catch(() => setAssets([])); } } }
  useEffect(() => { void loadCases().catch(() => setCases([])); request<Rehire[]>(`${base}/rehire-requests`).then(setRehire).catch(() => setRehire([])); }, [employee.id]);
  async function decision(caseId: string, result: string) { await request(`${base}/hr-cases/${caseId}/decision?decision=${result}`, { method: 'POST' }); await loadCases(); }
  const currentCase = cases.find(item => item.id === selectedCase);
  return <div className="people-lifecycle"><section className="people-subcard"><div className="people-card-heading"><div><p className="eyebrow">DUAL CONTROL WORKFLOW</p><h3>Onboarding &amp; separation cases</h3><p>Requests must be approved by a different user. Required onboarding or exit tasks must be complete first.</p></div></div><form className="people-inline-form" onSubmit={event => void save(event, async () => { const created = await request<HrCase>(`${base}/hr-cases`, { method: 'POST', body: JSON.stringify({ type, effectiveDate: date, reason }) }); await loadCases(); if (type === 'ONBOARDING') { await request(`${base}/hr-cases/${created.id}/requirements/apply-template`, { method: 'POST' }); await loadCases(); } }, 'HR case requested.') }><Field label="Case type"><select value={type} onChange={event => setType(event.target.value)}><option>ONBOARDING</option><option>SEPARATION</option></select></Field><Field label="Effective date"><input type="date" value={date} max={dateToday()} onChange={event => setDate(event.target.value)} required /></Field><Field label="Reason"><input value={reason} onChange={event => setReason(event.target.value)} required maxLength={250} /></Field><button className="security-submit" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Request case'}</button></form>
      <div className="people-case-list">{cases.map(item => <article className="people-case" key={item.id}><div className="people-record"><span><strong>{item.type.replaceAll('_', ' ')}</strong><small>{item.status} · Effective {new Date(`${item.effectiveDate}T12:00:00`).toLocaleDateString()}</small></span><span className={`platform-status-tag ${item.status === 'APPROVED' ? 'active' : item.status === 'PENDING' ? 'closed' : 'suspended'}`}>{item.status}</span></div>{item.status === 'PENDING' && <div className="people-form-actions"><button type="button" className="session-revoke" onClick={() => { setSelectedCase(item.id); if (item.type === 'ONBOARDING') request<Requirement[]>(`${base}/hr-cases/${item.id}/requirements`).then(setRequirements); else { request<Clearance[]>(`${base}/hr-cases/${item.id}/clearances`).then(setClearances); request<Asset[]>(`${base}/hr-cases/${item.id}/assets`).then(setAssets); } }}>Manage tasks</button><button type="button" className="session-revoke" disabled={item.requestedBy === currentUserId} onClick={() => void decision(item.id, 'REJECTED')}>Reject</button><button type="button" className="security-submit" disabled={item.requestedBy === currentUserId} onClick={() => void decision(item.id, 'APPROVED')}>Approve</button></div>}{item.type === 'SEPARATION' && item.status === 'APPROVED' && <FinalPaySettlementPanel
        employeeId={employee.id} caseId={item.id} currentUserId={currentUserId} request={request} />}</article>)}</div>
      {currentCase?.status === 'PENDING' && <div className="people-case-tasks"><strong>{currentCase.type} tasks</strong>{currentCase.type === 'ONBOARDING' ? <><div className="people-form-actions"><span>{requirements.filter(item => item.status === 'VERIFIED').length} / {requirements.length} verified</span><button type="button" className="session-revoke" onClick={() => void request(`${base}/hr-cases/${currentCase.id}/requirements/apply-template`, { method: 'POST' }).then(() => request<Requirement[]>(`${base}/hr-cases/${currentCase.id}/requirements`).then(setRequirements))}>Apply baseline checklist</button></div>{requirements.map(item => <div className="people-record" key={item.id}><span><strong>{item.label}</strong><small>{item.status}{item.mandatory ? ' · Required' : ''}</small></span>{item.status === 'PENDING' && <button type="button" className="session-revoke" onClick={() => void request(`${base}/hr-cases/${currentCase.id}/requirements/${item.id}/verification`, { method: 'PATCH', body: JSON.stringify({ status: 'VERIFIED', evidenceDocumentId: null }) }).then(() => request<Requirement[]>(`${base}/hr-cases/${currentCase.id}/requirements`).then(setRequirements))}>Verify</button>}</div>)}</> : <SeparationTasks caseId={currentCase.id} base={base} request={request} clearances={clearances} setClearances={setClearances} assets={assets} setAssets={setAssets} assetTag={assetTag} setAssetTag={setAssetTag} assetDescription={assetDescription} setAssetDescription={setAssetDescription} />}</div>}</section>
    <section className="people-subcard"><div className="people-card-heading"><div><p className="eyebrow">RETURNING EMPLOYEE</p><h3>Rehire requests</h3><p>Rehire approvals create a new employment episode and assignment.</p></div></div><form className="people-inline-form" onSubmit={event => void save(event, async () => { const item = await request<Rehire>(`${base}/rehire-requests`, { method: 'POST', body: JSON.stringify({ effectiveDate: date, employmentType: 'REGULAR', reason }) }); setRehire([item, ...rehire]); }, 'Rehire request submitted.') }><Field label="Effective date"><input type="date" value={date} max={dateToday()} onChange={event => setDate(event.target.value)} /></Field><Field label="Reason"><input value={reason} onChange={event => setReason(event.target.value)} required maxLength={250} /></Field><button className="session-revoke" type="submit" disabled={busy}>Request rehire</button></form><div className="people-record-list">{rehire.map(item => <div className="people-record" key={item.id}><span><strong>{item.status} · {item.employmentType.replaceAll('_', ' ')}</strong><small>{new Date(`${item.effectiveDate}T12:00:00`).toLocaleDateString()} · Requested by {item.requestedBy === currentUserId ? 'you' : 'another administrator'}</small></span>{item.status === 'PENDING' && <div className="people-form-actions"><button type="button" className="session-revoke" disabled={item.requestedBy === currentUserId} onClick={() => void request(`${base}/rehire-requests/${item.id}/reject`, { method: 'POST' }).then(() => request<Rehire[]>(`${base}/rehire-requests`).then(setRehire))}>Reject</button><button type="button" className="security-submit" disabled={item.requestedBy === currentUserId} onClick={() => void request(`${base}/rehire-requests/${item.id}/approve`, { method: 'POST' }).then(() => request<Rehire[]>(`${base}/rehire-requests`).then(setRehire))}>Approve</button></div>}</div>)}</div></section></div>;
}

function SeparationTasks({ caseId, base, request, clearances, setClearances, assets, setAssets, assetTag, setAssetTag, assetDescription, setAssetDescription }: { caseId: string; base: string; request: <T>(path: string, init?: RequestInit) => Promise<T>; clearances: Clearance[]; setClearances: (value: Clearance[]) => void; assets: Asset[]; setAssets: (value: Asset[]) => void; assetTag: string; setAssetTag: (value: string) => void; assetDescription: string; setAssetDescription: (value: string) => void }) {
  const [finalPay, setFinalPay] = useState<{ status: string } | null>(null);
  useEffect(() => { request<Array<{ status: string }>>(`${base}/hr-cases/${caseId}/final-pay`).then(rows => setFinalPay(rows[0] || null)).catch(() => setFinalPay(null)); }, [caseId]);
  return <><h4>Exit clearances</h4>{clearances.map(item => <div className="people-record" key={item.id}><span><strong>{item.label}</strong><small>{item.status}{item.required ? ' · Required' : ''}</small></span>{item.status === 'PENDING' && <button type="button" className="session-revoke" onClick={() => void request(`${base}/hr-cases/${caseId}/clearances/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'CLEARED' }) }).then(() => request<Clearance[]>(`${base}/hr-cases/${caseId}/clearances`).then(setClearances))}>Mark cleared</button>}</div>)}{!clearances.length && <button type="button" className="session-revoke" onClick={() => { for (const [code, label] of [['ACCESS_REVOKED','System access revoked'],['PAYROLL_CLOSED','Payroll closed'],['BENEFITS_CLOSED','Benefits closed']]) void request(`${base}/hr-cases/${caseId}/clearances`, { method: 'POST', body: JSON.stringify({ code, label, required: true }) }).then(() => request<Clearance[]>(`${base}/hr-cases/${caseId}/clearances`).then(setClearances)); }}>Add baseline exit clearances</button>}<h4>Company assets</h4><form className="people-inline-form" onSubmit={event => { event.preventDefault(); void request<Asset>(`${base}/hr-cases/${caseId}/assets`, { method: 'POST', body: JSON.stringify({ assetTag, description: assetDescription }) }).then(item => { setAssets([...assets, item]); setAssetTag(''); setAssetDescription(''); }); }}><Field label="Asset tag"><input value={assetTag} onChange={event => setAssetTag(event.target.value)} required maxLength={80} /></Field><Field label="Description"><input value={assetDescription} onChange={event => setAssetDescription(event.target.value)} required maxLength={200} /></Field><button type="submit" className="session-revoke">Add asset</button></form>{assets.map(item => <div className="people-record" key={item.id}><span><strong>{item.assetTag}</strong><small>{item.description} · {item.status}</small></span>{item.status === 'PENDING' && <button type="button" className="session-revoke" onClick={() => void request(`${base}/hr-cases/${caseId}/assets/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'RETURNED' }) }).then(() => request<Asset[]>(`${base}/hr-cases/${caseId}/assets`).then(setAssets))}>Mark returned</button>}</div>)}<h4>Final pay</h4><p className="people-muted">{finalPay ? `Handoff status: ${finalPay.status}` : 'No final-pay handoff requested.'}</p>{!finalPay && <button type="button" className="session-revoke" onClick={() => void request(`${base}/hr-cases/${caseId}/final-pay`, { method: 'POST' }).then(() => setFinalPay({ status: 'PENDING' }))}>Request final-pay handoff</button>}</>;
}

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="people-field"><span>{label}</span>{children}</label>; }
function SummaryLine({ label, value }: { label: string; value: string }) { return <div className="people-summary-line"><span>{label}</span><strong>{value}</strong></div>; }
function RecordTimeline({ title, rows }: { title: string; rows: Array<{ id: string; date: string; title: string; detail: string }> }) { return <section className="people-subcard"><h3>{title}</h3>{rows.length ? <div className="people-timeline">{rows.map(row => <article key={row.id}><i /><small>{new Date(`${row.date}T12:00:00`).toLocaleDateString()}</small><strong>{row.title}</strong><p>{row.detail}</p></article>)}</div> : <p className="people-muted">No history recorded yet.</p>}</section>; }
function RecordList({ items, empty }: { items: Array<{ id: string; title: string; meta: string }>; empty: string }) { return <div className="people-record-list">{items.map(item => <div className="people-record" key={item.id}><span><strong>{item.title}</strong><small>{item.meta}</small></span></div>)}{!items.length && <p className="people-muted">{empty}</p>}</div>; }
